const summaryDrift = `-- name: SummaryDrift :many
WITH src AS (
    SELECT store_id, business_date, count(*) FILTER (WHERE status = 'completed')::int AS tx,
           COALESCE(sum(grand_total) FILTER (WHERE status = 'completed'), 0)::numeric AS grand,
           count(*) FILTER (WHERE status = 'voided')::int AS voided
    FROM sales WHERE business_date >= $1::date GROUP BY store_id, business_date
)
SELECT src.store_id, src.business_date
FROM src LEFT JOIN store_kpi_daily k ON k.store_id = src.store_id AND k.business_date = src.business_date
WHERE k.store_id IS NULL OR k.transactions <> src.tx OR k.grand_total <> src.grand OR k.voided <> src.voided
UNION
SELECT k.store_id, k.business_date
FROM store_kpi_daily k
WHERE k.business_date >= $1::date AND (k.transactions > 0 OR k.voided > 0)
  AND NOT EXISTS (SELECT 1 FROM sales s WHERE s.store_id = k.store_id AND s.business_date = k.business_date)
`

type SummaryDriftRow struct {
	StoreID      uuid.UUID `json:"store_id"`
	BusinessDate time.Time `json:"business_date"`
}

// Reconcile: slices in the window whose summary disagrees with the source (or is missing / stale).
func (q *Queries) SummaryDrift(ctx context.Context, since time.Time) ([]SummaryDriftRow, error) {
	rows, err := q.db.Query(ctx, summaryDrift, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummaryDriftRow{}
	for rows.Next() {
		var i SummaryDriftRow
		if err := rows.Scan(&i.StoreID, &i.BusinessDate); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const summaryReturnDrift = `-- name: SummaryReturnDrift :many
WITH src AS (
    SELECT sr.store_id, (sr.created_at AT TIME ZONE st.timezone)::date AS business_date, COALESCE(sum(sri.amount), 0)::numeric AS refund
    FROM sale_returns sr JOIN sale_return_items sri ON sri.return_id = sr.id JOIN stores st ON st.id = sr.store_id
    WHERE sr.created_at >= $1::date::timestamptz - interval '1 day'
    GROUP BY sr.store_id, 2
)
SELECT src.store_id, src.business_date
FROM src LEFT JOIN store_kpi_daily k ON k.store_id = src.store_id AND k.business_date = src.business_date
WHERE src.business_date >= $1::date AND (k.store_id IS NULL OR k.refund <> src.refund)
`

type SummaryReturnDriftRow struct {
	StoreID      uuid.UUID `json:"store_id"`
	BusinessDate time.Time `json:"business_date"`
}

// Refund totals per store/local day: source (sale_return_items) vs the summary column.
func (q *Queries) SummaryReturnDrift(ctx context.Context, since time.Time) ([]SummaryReturnDriftRow, error) {
	rows, err := q.db.Query(ctx, summaryReturnDrift, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummaryReturnDriftRow{}
	for rows.Next() {
		var i SummaryReturnDriftRow
		if err := rows.Scan(&i.StoreID, &i.BusinessDate); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
